' Create the schedule definition.
definition.StartDateTime = New DateTime(2003, 3, 1, 14, 0, 0)
Dim recurrence As New WeeklyRecurrence()
Dim days As New DaysOfWeekSelector()
days.Monday = True
days.Tuesday = True
days.Wednesday = True
days.Thursday = True
days.Friday = True
days.Saturday = False
days.Sunday = False
